#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef struct Entry {
    char *key; int val;
    struct Entry *next;
} Entry;

typedef struct { Entry **b; size_t m, n; } Table;

static uint32_t fnv1a(const char *s) {
    uint32_t h = 2166136261u;
    for (; *s; s++) { h ^= (unsigned char)*s; h *= 16777619u; }
    return h;
}

int t_init(Table *t, size_t m) {
    t->b = calloc(m, sizeof *t->b);
    t->m = m; t->n = 0;
    return t->b ? 0 : -1;
}

static int grow(Table *t) {
    size_t nm = t->m * 2;
    Entry **nb = calloc(nm, sizeof *nb);
    if (!nb) return -1;
    for (size_t i = 0; i < t->m; i++)
        for (Entry *e = t->b[i], *nx; e; e = nx) {
            nx = e->next;                    /* relink, do not copy */
            size_t j = fnv1a(e->key) % nm;
            e->next = nb[j]; nb[j] = e;
        }
    free(t->b); t->b = nb; t->m = nm;
    return 0;
}

int t_put(Table *t, const char *k, int v) {
    size_t i = fnv1a(k) % t->m;
    for (Entry *e = t->b[i]; e; e = e->next)
        if (!strcmp(e->key, k)) { e->val = v; return 0; }
    if (t->n + 1 > t->m * 3 / 4) { if (grow(t)) return -1; i = fnv1a(k) % t->m; }
    Entry *e = malloc(sizeof *e);
    if (!e) return -1;
    e->key = strdup(k); e->val = v;
    e->next = t->b[i]; t->b[i] = e; t->n++;
    return 0;
}

int t_get(const Table *t, const char *k, int *out) {
    for (Entry *e = t->b[fnv1a(k) % t->m]; e; e = e->next)
        if (!strcmp(e->key, k)) { *out = e->val; return 1; }
    return 0;
}

/* linear probing lookup; slot states: EMPTY, FULL, TOMB */
int find(const Slot *t, size_t m, int key) {
    size_t i = (size_t)key % m;
    for (size_t step = 0; step < m; step++) {
        const Slot *s = &t[i];
        if (s->state == EMPTY) return -1;       /* chain ends */
        if (s->state == FULL && s->key == key) return (int)i;
        i = (i + 1) % m;                         /* skip TOMB */
    }
    return -1;
}
